// ─────────────────────────────────────────────────────────────────────────
//  01 · batched customer loading★★★
//  concepts: N+1 · batch fetching · IN-list limits
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.function.*;

class Exercise {

    record Order(long id, long customerId) {}
    record Customer(long id, String name) {}
    record OrderRow(long orderId, String customerName) {}

    /** Rows with customer names, loading customers in IN-list batches of at most batchSize ids. */
    static List<OrderRow> withCustomers(List<Order> orders, Function<Set<Long>, Map<Long, Customer>> loadCustomers, int batchSize) {
        if (batchSize < 1) throw new IllegalArgumentException("batchSize must be >= 1");
        var ids = new ArrayList<>(new LinkedHashSet<>(orders.stream().map(Order::customerId).toList()));
        var customers = new HashMap<Long, Customer>();
        for (int i = 0; i < ids.size(); i += batchSize) {
            customers.putAll(loadCustomers.apply(new LinkedHashSet<>(ids.subList(i, Math.min(i + batchSize, ids.size())))));
        }
        return orders.stream()
            .map(o -> new OrderRow(o.id(), Optional.ofNullable(customers.get(o.customerId())).map(Customer::name).orElse("(unknown)")))
            .toList();
    }

    static Function<Set<Long>, Map<Long, Customer>> recording(List<Set<Long>> calls) {
        return ids -> {
            calls.add(new TreeSet<>(ids));
            var m = new HashMap<Long, Customer>();
            for (long id : ids) if (id != 99) m.put(id, new Customer(id, "c" + id));
            return m;
        };
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("distinct ids are loaded in batches", () -> {
            var calls = new ArrayList<Set<Long>>();
            withCustomers(List.of(new Order(1, 1), new Order(2, 2), new Order(3, 3), new Order(4, 1), new Order(5, 4)), recording(calls), 2);
            eq(calls, List.of(Set.of(1L, 2L), Set.of(3L, 4L)));
        });
        test("rows keep the order sequence", () -> {
            var rows = withCustomers(List.of(new Order(10, 2), new Order(11, 1)), recording(new ArrayList<>()), 100);
            eq(rows, List.of(new OrderRow(10, "c2"), new OrderRow(11, "c1")));
        });
        test("the number of calls rounds up", () -> {
            var calls = new ArrayList<Set<Long>>();
            var orders = new ArrayList<Order>();
            for (long i = 1; i <= 1001; i++) orders.add(new Order(i, i));
            withCustomers(orders, recording(calls), 500);
            eq(calls.size(), 3);
            ok(calls.stream().allMatch(c -> c.size() <= 500), "a batch exceeded the limit");
        });
        test("a missing customer gets a placeholder", () -> eq(withCustomers(List.of(new Order(1, 99)), recording(new ArrayList<>()), 10).get(0).customerName(), "(unknown)"));
        test("no orders, no calls (boundary)", () -> {
            var calls = new ArrayList<Set<Long>>();
            ok(withCustomers(List.of(), recording(calls), 10).isEmpty() && calls.isEmpty(), "no calls expected");
            raises(IllegalArgumentException.class, () -> withCustomers(List.of(), recording(calls), 0));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
Deduplicate with a `LinkedHashSet`, slice it into batches, merge every batch's result into one map, then build the rows:

```java
var ids = new ArrayList<>(new LinkedHashSet<>(orders.stream().map(Order::customerId).toList()));
var customers = new HashMap<Long, Customer>();
for (int i = 0; i < ids.size(); i += batchSize) {
    customers.putAll(loadCustomers.apply(new LinkedHashSet<>(ids.subList(i, Math.min(i + batchSize, ids.size())))));
}
return orders.stream()
    .map(o -> new OrderRow(o.id(), Optional.ofNullable(customers.get(o.customerId())).map(Customer::name).orElse("(unknown)")))
    .toList();
```

This is exactly what Hibernate does for a lazy `@ManyToOne` with a batch size: one query per batch instead of one per row.

