//  02 · the @Transactional proxy and self-invocation★★★
//  concepts: JDK dynamic proxies · rollback rules · REQUIRED · this.method() bypass
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

class Exercise {

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    @interface Transactional {}

    /** Records what a PlatformTransactionManager was asked to do. */
    static class TxManager {
        final List<String> log = new ArrayList<>();
        boolean active;
        void begin() { active = true; log.add("begin"); }
        void commit() { active = false; log.add("commit"); }
        void rollback() { active = false; log.add("rollback"); }
    }

    interface OrderService {
        @Transactional void placeOrder(String id);
        @Transactional void refund(String id) throws Exception;
        @Transactional void checkout(String id);
        void importAll(List<String> ids);
        void importAllViaSelf(List<String> ids);
        int placed();
    }

    /** A proxy implementing iface that runs @Transactional methods of target inside a transaction. */
    static <T> T transactional(T target, Class<T> iface, TxManager tx) {
        throw new UnsupportedOperationException("TODO: Proxy.newProxyInstance with an InvocationHandler that begins, commits or rolls back");
    }

    static class DefaultOrderService implements OrderService {
        final TxManager tx;
        final List<String> seen = new ArrayList<>();
        OrderService self;                        // the injected proxy (the usual fix for self-invocation)

        DefaultOrderService(TxManager tx) { this.tx = tx; }

        public void placeOrder(String id) {
            seen.add(id + (tx.active ? " in tx" : " NO tx"));
            if (id.isBlank()) throw new IllegalArgumentException("blank order id");
        }
        public void refund(String id) throws Exception {
            seen.add("refund " + id);
            throw new Exception("refund declined by the bank");
        }
        public void checkout(String id) { self.placeOrder(id); }
        public void importAll(List<String> ids) { for (var id : ids) this.placeOrder(id); }   // self-invocation
        public void importAllViaSelf(List<String> ids) { for (var id : ids) self.placeOrder(id); }
        public int placed() { return seen.size(); }
    }

    record Fixture(TxManager tx, DefaultOrderService target, OrderService proxy) {}

    static Fixture fixture() {
        var tx = new TxManager();
        var target = new DefaultOrderService(tx);
        var proxy = transactional(target, OrderService.class, tx);
        target.self = proxy;
        return new Fixture(tx, target, proxy);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a @Transactional call through the proxy begins and commits", () -> {
            var f = fixture();
            f.proxy().placeOrder("o1");
            eq(List.of(f.tx().log, f.target().seen), List.of(List.of("begin", "commit"), List.of("o1 in tx")));
        });
        test("a runtime exception rolls back and reaches the caller unwrapped", () -> {
            var f = fixture();
            raises(IllegalArgumentException.class, () -> f.proxy().placeOrder(" "), "blank order id");
            eq(f.tx().log, List.of("begin", "rollback"));
        });
        test("a checked exception COMMITS by default", () -> {
            var f = fixture();
            raises(Exception.class, () -> f.proxy().refund("o1"), "declined");
            eq(f.tx().log, List.of("begin", "commit"));
        });
        test("self-invocation bypasses the proxy: this.placeOrder runs without a transaction", () -> {
            var f = fixture();
            f.proxy().importAll(List.of("a", "b"));
            eq(List.of(f.tx().log, f.target().seen), List.of(List.of(), List.of("a NO tx", "b NO tx")));
        });
        test("calling through the injected proxy gives each call its own transaction", () -> {
            var f = fixture();
            f.proxy().importAllViaSelf(List.of("a", "b"));
            eq(f.tx().log, List.of("begin", "commit", "begin", "commit"));
        });
        test("a nested @Transactional call joins the active transaction (REQUIRED)", () -> {
            var f = fixture();
            f.proxy().checkout("o1");
            eq(List.of(f.tx().log, f.target().seen), List.of(List.of("begin", "commit"), List.of("o1 in tx")));
        });
        test("a method without @Transactional is forwarded with its result and no transaction (boundary)", () -> {
            var f = fixture();
            f.target().seen.add("earlier");
            eq(List.of(f.proxy().placed(), f.tx().log.size()), List.of(1, 0));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

