import static bootcamp.Check.*;

import java.util.*;
import java.util.function.*;

class Exercise {

    static class LazyInitializationException extends RuntimeException { LazyInitializationException(String m) { super(m); } }
    static class EntityNotFoundException extends RuntimeException { EntityNotFoundException(String m) { super(m); } }

    /** A Hibernate Session over a customers table (id -> name). */
    static class Session implements AutoCloseable {
        final Map<Long, String> customers;
        int queries;
        boolean open = true;

        Session(Map<Long, String> customers) { this.customers = customers; }

        /** one SELECT; a closed session cannot query */
        String selectCustomerName(long id) {
            if (!open) throw new IllegalStateException("Session is closed");
            queries++;
            return customers.get(id);
        }

        @Override public void close() { open = false; }
    }

    /** What order.getCustomer() returns for a LAZY @ManyToOne: an uninitialised proxy. */
    static class LazyCustomer {
        final long id;
        final Session session;
        private String name;
        private boolean initialized;

        LazyCustomer(long id, Session session) { this.id = id; this.session = session; }

        /** The id is known without loading the row. */
        long getId() { return id; }

        /** First touch loads the row once; after the session closed an uninitialised proxy cannot load. */
        String getName() {
            throw new UnsupportedOperationException("TODO: initialise on first touch; no open session -> LazyInitializationException");
        }
    }

    record Order(long id, LazyCustomer customer) {}
    record OrderView(long id, String customerName) {}

    /** Given: the repository call; the customer stays a lazy proxy. */
    static Order loadOrder(Session s, long orderId, long customerId) { return new Order(orderId, new LazyCustomer(customerId, s)); }

    /** The service method: open a session, load, map to a DTO while the session is open, always close it. */
    static OrderView view(Supplier<Session> sessions, long orderId, long customerId) {
        throw new UnsupportedOperationException("TODO: try-with-resources, and touch the customer before the session closes");
    }

    static final Map<Long, String> CUSTOMERS = Map.of(7L, "Ana");

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("the first touch inside the session loads the customer once", () -> {
            var s = new Session(CUSTOMERS);
            var order = loadOrder(s, 1, 7);
            eq(List.of(order.customer().getName(), order.customer().getName(), s.queries), List.of("Ana", "Ana", 1));
        });
        test("touching the proxy after the session closed throws LazyInitializationException", () -> {
            Order order;
            try (var s = new Session(CUSTOMERS)) {
                order = loadOrder(s, 1, 7);     // the controller gets the entity back...
            }
            raises(LazyInitializationException.class, () -> order.customer().getName(), "no Session");   // ...and serialises it
        });
        test("a proxy initialised before close stays readable afterwards (boundary)", () -> {
            var s = new Session(CUSTOMERS);
            var order = loadOrder(s, 1, 7);
            order.customer().getName();
            s.close();
            eq(List.of(order.customer().getName(), s.queries), List.of("Ana", 1));
        });
        test("reading the id needs no query, even after close", () -> {
            var s = new Session(CUSTOMERS);
            var order = loadOrder(s, 1, 7);
            s.close();
            eq(List.of(order.customer().getId(), s.queries), List.of(7L, 0));
        });
        test("the service maps to a DTO inside the session and closes it", () -> {
            var opened = new ArrayList<Session>();
            var view = view(() -> { var s = new Session(CUSTOMERS); opened.add(s); return s; }, 1, 7);
            eq(view, new OrderView(1, "Ana"));
            ok(opened.size() == 1 && !opened.get(0).open, "the service must open one session and close it");
        });
        test("a missing customer fails, and the session is still closed", () -> {
            var opened = new ArrayList<Session>();
            raises(EntityNotFoundException.class, () -> view(() -> { var s = new Session(CUSTOMERS); opened.add(s); return s; }, 1, 99), "99");
            ok(opened.size() == 1 && !opened.get(0).open, "the session was left open after the failure");
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

