    static class EntityNotFoundException extends RuntimeException { EntityNotFoundException(String m) { super(m); } }

    /** A Hibernate Session over a customers table (id -> name). */
    static class Session implements AutoCloseable {
        final Map<Long, String> customers;
        int queries;
        boolean open = true;

        Session(Map<Long, String> customers) { this.customers = customers; }

        /** one SELECT; a closed session cannot query */
        String selectCustomerName(long id) {
