        /** The id is known without loading the row. */
        long getId() { return id; }

        /** First touch loads the row once; after the session closed an uninitialised proxy cannot load. */
        String getName() {
            if (!initialized) {
                if (!session.open) throw new LazyInitializationException("could not initialize proxy [Customer#" + id + "] - no Session");
                String loaded = session.selectCustomerName(id);
