            var s = new Session(CUSTOMERS);
            var order = loadOrder(s, 1, 7);
            eq(List.of(order.customer().getName(), order.customer().getName(), s.queries), List.of("Ana", "Ana", 1));
        });
        test("touching the proxy after the session closed throws LazyInitializationException", () -> {
            Order order;
            try (var s = new Session(CUSTOMERS)) {
                order = loadOrder(s, 1, 7);     // the controller gets the entity back...
            }
            raises(LazyInitializationException.class, () -> order.customer().getName(), "no Session");   // ...and serialises it
        });
        test("a proxy initialised before close stays readable afterwards (boundary)", () -> {
            var s = new Session(CUSTOMERS);
            var order = loadOrder(s, 1, 7);
            order.customer().getName();
            s.close();
            eq(List.of(order.customer().getName(), s.queries), List.of("Ana", 1));
        });
        test("reading the id needs no query, even after close", () -> {
            var s = new Session(CUSTOMERS);
            var order = loadOrder(s, 1, 7);
            s.close();
            eq(List.of(order.customer().getId(), s.queries), List.of(7L, 0));
        });
        test("the service maps to a DTO inside the session and closes it", () -> {
            var opened = new ArrayList<Session>();
            var view = view(() -> { var s = new Session(CUSTOMERS); opened.add(s); return s; }, 1, 7);
            eq(view, new OrderView(1, "Ana"));
            ok(opened.size() == 1 && !opened.get(0).open, "the service must open one session and close it");
        });
        test("a missing customer fails, and the session is still closed", () -> {
            var opened = new ArrayList<Session>();
            raises(EntityNotFoundException.class, () -> view(() -> { var s = new Session(CUSTOMERS); opened.add(s); return s; }, 1, 99), "99");
            ok(opened.size() == 1 && !opened.get(0).open, "the session was left open after the failure");
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

